'use strict';
const K='manual_criaturas_vol1_2026', app=document.getElementById('app');
const esc=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const ARCHIVE_ORDER=['lago','lago2','baile','baile2','vampiro','vampiro2','lobo','lobo2','retrato','retrato2','estacao','estacao2','museu','museu2','bolsonaros'];
const keys=ARCHIVE_ORDER.filter(id=>CASES[id]);
const LEVELS=['Iniciante','Intermediário','Avançado'];

const blank=id=>({gearFlags:{},powderUses:0,powdered:[],officeFlags:{},extraFlags:{},caseId:id,view:'brief',evidence:[],witness:[],trust:0,selectedTheory:null,theory:null,outcome:null,activeScene:Object.keys(CASES[id].scenes)[0],modal:null,reply:null,phase:0,puzzleInput:[],puzzleSolved:false,ritualComplete:false,pretty:true,interlude:null,boardSolved:false,boardPairs:[],boardChoice:null,boardMistakes:0,roleContributions:{},echoClaimed:false,dailyOutcomeDate:null});
let saved={cases:{},completions:{},histories:{},current:'lago'};try{let a=JSON.parse(localStorage.getItem(K));if(a&&a.cases)saved={...saved,...a}}catch(e){}
// Carteira e progresso são locais ao aparelho e compartilham o salvamento de sempre.
if(!Number.isFinite(saved.wallet))saved.wallet=120;
if(!Array.isArray(saved.owned))saved.owned=[];
if(!saved.stock||typeof saved.stock!=='object')saved.stock={powder:0,ward:0,incense:0,lantern:0};
if(!saved.rooms||typeof saved.rooms!=='object')saved.rooms={};
if(!saved.contracts||typeof saved.contracts!=='object')saved.contracts={};
if(!saved.dailyPayout||typeof saved.dailyPayout!=='object')saved.dailyPayout={};
if(!saved.soundtrack)saved.soundtrack='gothic';
if(!saved.paid||typeof saved.paid!=='object')saved.paid={};
if(!saved.economyV1){
 for(const id of keys){if(saved.completions?.[id]||saved.cases?.[id]?.outcome||saved.histories?.[id]?.outcome){saved.wallet+=55;saved.paid[id]=true}}
 saved.economyV1=true;
 try{localStorage.setItem(K,JSON.stringify(saved))}catch(e){}
}
const own=id=>saved.owned.includes(id);
const charges=id=>Math.max(0,Number(saved.stock[id])||0);
const gearOn=id=>Boolean(s.gearFlags?.[id]);

const rCase=()=>RESEARCH_CASES[s.caseId];
const worldHistory=id=>saved.histories?.[id]||((saved.cases?.[id]?.outcome)?{outcome:saved.cases[id].outcome,boardSolved:!!saved.cases[id].boardSolved}:null);
const worldEcho=()=>{const r=rCase();return r&&worldHistory(r.link)};
const favorable=outcome=>outcome==='libertar'||outcome==='negociar';
const worldStats=()=>{let trust=45,veil=55,research=0;for(const id of keys){const h=worldHistory(id);if(!h)continue;research+=h.boardSolved?2:1;trust+=favorable(h.outcome)?7:h.outcome==='expor'?1:-7;veil+=h.outcome==='libertar'?7:h.outcome==='negociar'?3:h.outcome==='expor'?-3:-7}return {trust:Math.max(0,Math.min(100,trust)),veil:Math.max(0,Math.min(100,veil)),research}};
const activeSpecialty=()=>net.mode==='coop'&&net.inGame?net.specialty:'shared';
const canInspect=id=>net.mode!=='coop'||!net.inGame||clueOwner(s.caseId,id)===net.slot||s.evidence.includes(id);
const echoTrust=()=>{const e=worldEcho();return !e?0:(favorable(e.outcome)?1:e.outcome==='selar'?-1:0)+(e.boardSolved?1:0)};
const worldEchoText=()=>{const e=worldEcho(),r=rCase();if(!e)return '';const f=favorable(e.outcome);return `${r.memory} ${f?'Sua decisão anterior conquistou um contato disposto a colaborar.':'Sua decisão anterior gerou desconfiança ou exposição pública; as testemunhas estão mais cautelosas.'} ${e.boardSolved?'Uma conexão comprovada no quadro anterior oferece um bônus de confiança.':'A conexão entre aquelas provas não foi demonstrada.'}`};
function claimEcho(){if(!worldEcho()||s.echoClaimed)return;const target=Object.keys(c().clues)[8];s.echoClaimed=true;if(!s.evidence.includes(target))s.evidence.push(target);persist();toast('Rastro cruzado catalogado: +1 pista!');render()}
function boardPick(id){if(s.boardSolved||!s.evidence.includes(id))return;const a=s.boardPairs||[];s.boardPairs=a.includes(id)?a.filter(x=>x!==id):[...a.slice(-1),id];render()}
function boardAnswer(i){if(s.boardSolved)return;s.boardChoice=i;render()}
function boardCheck(){if(s.boardSolved)return;const r=rCase();if(s.boardPairs.length!==2||s.boardChoice===null){toast('Escolha duas pistas e uma conclusão.');return}const pair=[...s.boardPairs].sort().join('|'),correct=[...r.pair].sort().join('|');if(pair===correct&&s.boardChoice===r.answer){s.boardSolved=true;s.boardPairs=[];s.boardChoice=null;persist();playEffect('reveal');toast('Conexão provada! O arquivo foi atualizado.');render()}else{s.boardMistakes=(s.boardMistakes||0)+1;s.boardChoice=null;persist();toast('Essa ligação não explica os fatos. Compare as evidências.');render()}}
function researchBoard(){const r=rCase(),found=s.evidence.filter(id=>Object.hasOwn(c().clues,id));return `<section class="section researchBoard"><button class="backBtn" data-view="hub">← Voltar aos locais</button><div class="eyebrow">Laboratório · Arquivo ${c().number}</div><h2>Quadro de provas</h2><p class="lead">${esc(r.question)}</p>${net.inGame&&net.mode==='coop'?`<div class="roleNotice">Os nove indícios deste caso são distribuídos entre os especialistas. Juntem descobertas e pareceres para formular a hipótese coletiva.</div>`:''}<div class="boardStatus">${s.boardSolved?'✦ CONEXÃO DECIFRADA':'Escolha DUAS provas relacionadas'}</div><div class="boardEvidence">${found.map(id=>{const e=c().clues[id],selected=s.boardPairs.includes(id);return `<button class="boardClue ${selected?'picked':''}" data-board-clue="${id}" ${s.boardSolved?'disabled':''}><span>${selected?'✓':'+'}</span><strong>${esc(e.name)}</strong><small>${net.mode==='coop'&&net.inGame?roleAt(clueOwner(s.caseId,id)).symbol+' '+roleAt(clueOwner(s.caseId,id)).name:researchSpecialty(s.caseId,id)==='analyst'?'⌕ Material':researchSpecialty(s.caseId,id)==='sensitive'?'✧ Manifestação':'◇ Comum'}</small></button>`}).join('')}</div>${!found.length?'<p>Investigue os cenários para reunir provas.</p>':''}<div class="eyebrow">A dedução</div>${r.choices.map((a,i)=>`<button class="boardTheory ${s.boardChoice===i?'picked':''}" data-board-choice="${i}" ${s.boardSolved||gearOn('pendulum')&&i===(r.answer+1)%3?'disabled':''}>${s.boardChoice===i?'◉':'○'} ${esc(a)}</button>`).join('')}${s.boardSolved?`<div class="secretRevelation"><strong>Prova demonstrada</strong><p>${esc(r.conclusion)}</p><p>A equipe poderá usar essa conexão em outras investigações.</p></div>`:`<div class="boardTip">Dica: investigue sinais de diferentes origens e veja se os dois documentos sustentam uma mesma explicação. ${s.boardMistakes?'Tentativas sem êxito: '+s.boardMistakes+'.':''}</div><button class="btn" data-action="board-check" ${s.boardPairs.length===2&&s.boardChoice!==null?'':'disabled'}>Testar ligação →</button>`}${officeTools()}${own('pendulum')?`<button class="toolAction" data-gear="pendulum" ${gearOn('pendulum')||s.boardSolved?'disabled':''}>◈ ${gearOn('pendulum')?'✓ Leitura realizada':'Usar Pêndulo de Prata · eliminar uma teoria'}</button>`:''}<button class="btn outline" data-view="dossier">Consultar dossiê →</button></section>`}

const gearScene=()=>Object.keys(c().scenes)[1];
const hasRoom=id=>!!saved.rooms[id] || (net.mode==='coop'&&net.online&&!!net.teamUpgrades?.[id]);
const teamRoom=id=>hasRoom(id)||(net.mode==='coop'&&net.inGame&&net.players.some(p=>p&&p.rooms?.[id]));
const roomUsed=id=>!!s.officeFlags?.[id];
const trustNow=()=>s.witness.reduce((v,x)=>v+(c().witness.questions[x]?.trust||0),0)+(gearOn('recorder')?2:0)+(gearOn('amulet')?2:0)+echoTrust()+(teamRoom('sanctuary')?2:0)+(teamRoom('observatory')&&worldEcho()?1:0)+(gearOn('incense')?2:0);
const rewardFor=id=>({Iniciante:70,Intermediário:90,Avançado:125}[difficulty(id)]||90);
const recordMoney=()=>{if(!s.outcome||saved.paid[s.caseId])return;const extra=s.theory===c().correct?20:0;const award=rewardFor(s.caseId)+extra;saved.wallet+=award;saved.paid[s.caseId]=true;s.rewardLast=award;};
const localDay=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const fCase=id=>s.caseId===id?s:(saved.cases?.[id]||{});
const contractId=(id,task)=>id+':'+task;
const claimed=(id,task)=>!!saved.contracts[contractId(id,task)];
function claimContract(id,task){const taskObj=CONTRACTS.find(k=>k.id===task);if(!CASES[id]||!taskObj||claimed(id,task))return;const st=fCase(id);if(!taskObj.valid(st)){toast('Contrato ainda não foi cumprido.');return}saved.contracts[contractId(id,task)]=true;saved.wallet+=taskObj.reward;saveWallet();toast('Contrato pago: +'+taskObj.reward+' créditos');render()}
function claimDaily(){const d=localDay();if(saved.dailyPayout[d]){toast('Plantão do dia já remunerado.');return}const last=fCase(s.caseId);if(!last.outcome||last.dailyOutcomeDate!==d){toast('Encerre um caso hoje para receber o plantão.');return}saved.dailyPayout[d]=s.caseId;saved.wallet+=38;saveWallet();toast('Plantão concluído! +38 créditos');render()}
function upgradeRoom(id){const r=OFFICE_ROOMS[id];if(!r||hasRoom(id))return;if(saved.wallet<r.cost){toast('Créditos insuficientes. Cumpra contratos ou conclua casos.');return}saved.wallet-=r.cost;saved.rooms[id]=true;s.trust=trustNow();saveWallet();playEffect('buy');toast('O Instituto foi ampliado: '+r.name);render()}
function officeIndex(){if(!hasRoom('library')||s.evidence.length<3){toast('Construa a Biblioteca e encontre ao menos três pistas.');return}const target=rCase().pair.find(k=>!s.evidence.includes(k));s.officeFlags.library=true;persist();toast(target?'O índice sugere buscar: '+c().clues[target].name:'As duas evidências-chave já estão entre suas pistas.');render()}
function officeAnalysis(){if(!hasRoom('laboratory')||roomUsed('laboratory')||s.evidence.length<2||s.outcome)return;if(net.mode==='coop'&&net.online&&roleAt(net.slot).id!=='analyst'){toast('A análise de amostras exige o Analista.');return}const target=Object.keys(c().clues).find(id=>!s.evidence.includes(id)&&canInspect(id)&&researchSpecialty(s.caseId,id)==='analyst');if(!target){toast('Todos os vestígios materiais já foram catalogados.');return}s.officeFlags.laboratory=true;s.evidence.push(target);s.modal=target;persist();toast('Amostra processada! Uma pista material foi identificada.');render()}
function gearCamera(){if(!own('camera')||gearOn('camera')||s.outcome)return;const loc=c().scenes[s.activeScene],id=loc?.items?.find(k=>!s.evidence.includes(k)&&canInspect(k));if(!id){toast('Nenhuma pista fotografável neste local.');return}s.gearFlags.camera=true;s.evidence.push(id);s.modal=id;persist();toast('Fotografia taumatúrgica arquivada.');render()}
function gearPendulum(){if(!own('pendulum')||gearOn('pendulum')||s.outcome)return;s.gearFlags.pendulum=true;persist();toast('O pêndulo descartou uma explicação falsa.');render()}
function gearIncense(){if(!charges('incense')||gearOn('incense')||s.outcome)return;saved.stock.incense--;s.gearFlags.incense=true;s.trust=trustNow();persist();toast('Memórias restauradas · +2 confiança');render()}
function gearLantern(){if(!charges('lantern')||gearOn('lantern')||s.outcome)return;const loc=c().scenes[s.activeScene],id=loc?.items?.find(k=>!s.evidence.includes(k)&&canInspect(k));if(!id){toast('Não há vestígio acessível para iluminar aqui.');return}saved.stock.lantern--;s.gearFlags.lantern=true;s.evidence.push(id);s.modal=id;persist();toast('A lanterna revelou um vestígio.');render()}
function officeTools(){return `<div class="equipmentActions"><div class="eyebrow">Apoio da sede</div>${hasRoom('laboratory')?`<button class="toolAction" data-office="analysis" ${roomUsed('laboratory')||s.evidence.length<2||s.outcome?'disabled':''}>⚗ ${roomUsed('laboratory')?'Amostra já processada':'Analisar amostra material · 1 vez por caso'}</button>`:''}${hasRoom('library')?`<button class="toolAction" data-office="index" ${s.evidence.length<3?'disabled':''}>▤ Consultar índice · indicação de evidência decisiva</button>`:''}${hasRoom('observatory')?`<div class="officeEvidence">✧ Observatório: ${esc(rCase().memory)} ${worldEcho()?'O rastro anterior fortalece seu testemunho.':'A conexão ainda não foi registrada no outro arquivo.'}</div>`:''}</div>`}
function officePage(){const ws=worldStats();return `<section class="officeHero" style="background-image:linear-gradient(0deg,#07161d 0%,transparent 65%),url('assets/headquarters.svg')"><button class="backBtn" data-view="collection">← Voltar aos arquivos</button><div class="officeInstallations" aria-label="Ala principal do instituto">${Object.entries(OFFICE_ROOMS).map(([id,r],i)=>`<div class="officeSigil ${hasRoom(id)?'installed':''} sigil-${id}" title="${r.name}"><span>${r.icon}</span><small>${hasRoom(id)?'ATIVO':'FECHADO'}</small></div>`).join('')}</div><div class="officeHeroText"><div class="eyebrow">Instituto de Estudos do Véu</div><h1>Sede dos<br>Pesquisadores</h1><p>Seu refúgio entre um mistério e outro. Cada nova ala melhora suas pesquisas.</p></div></section><section class="section officePage"><div class="officeQuick"><div><small>CRÉDITOS</small><b>${saved.wallet} ◈</b></div><div><small>ALA CONSTRUÍDA</small><b>${Object.keys(OFFICE_ROOMS).filter(hasRoom).length}/4</b></div><div><small>CASOS</small><b>${totalCompleted()}/${keys.length}</b></div></div><div class="officeSectionTitle"><div class="eyebrow">Ampliação do Instituto</div><h2>Novas alas</h2><p>As melhorias permanecem compradas e beneficiam os ${keys.length} arquivos.</p></div><div class="officeGrid">${Object.entries(OFFICE_ROOMS).map(([id,r])=>`<article class="officeCard ${hasRoom(id)?'built':''}"><div class="officeArt"><img src="${r.art}" alt="Ilustração da ${esc(r.name)}"/></div><div class="officeCardBody"><small>${hasRoom(id)?'✓ ALA ATIVA':'ALA DISPONÍVEL'}</small><h3>${r.name}</h3><p>${r.desc}</p><div class="benefit">${r.benefit}</div><button class="buyGear" data-office-buy="${id}" ${hasRoom(id)||saved.wallet<r.cost?'disabled':''}>${hasRoom(id)?'✓ Construída':'Construir · '+r.cost+' ◈'}</button></div></article>`).join('')}</div><div class="officeSectionTitle"><div class="eyebrow">Trabalho remunerado</div><h2>Contratos de campo</h2><p>Complete tarefas adicionais em cada investigação para financiar sua sede. As recompensas de cada contrato são únicas.</p></div>${contractList()}<button class="btn outline" data-view="contracts">Ver contratos dos 14 casos →</button><div class="dailyBox"><div class="eyebrow">Plantão diário</div><h3>Retorne ao trabalho</h3><p>Conclua ou rejogue uma investigação hoje e resgate 38 créditos. Limite de um plantão pago por dia neste aparelho.</p><button class="buyGear" data-action="claim-daily" ${saved.dailyPayout[localDay()]||!fCase(s.caseId).outcome||fCase(s.caseId).dailyOutcomeDate!==localDay()?'disabled':''}>${saved.dailyPayout[localDay()]?'✓ Plantão de hoje pago':'Resgatar plantão · +38 ◈'}</button></div><div class="officeSectionTitle"><div class="eyebrow">Ambiente e conforto</div><h2>Som e efeitos</h2></div><div class="audioControl"><button class="toolAction" data-action="audio">${sound.playing?'♫ Desligar trilha':'♫ Ligar trilha original'}</button><button class="toolAction" data-action="soundtrack">Trocar atmosfera: ${({gothic:'Gótico',mist:'Névoa',astral:'Astral'}[saved.soundtrack])}</button></div><p class="caption">Trilha gerada pelo próprio navegador, sem arquivos de música externa. O áudio começa desligado, respeita a interação do usuário e pode ser desligado a qualquer momento.</p><button class="btn" data-view="shop">Visitar a loja de equipamentos →</button></section>`}
function contractList(){return `<div class="contractGrid">${CONTRACTS.map(t=>{const ok=t.valid(s),done=claimed(s.caseId,t.id);return `<div class="contractCard"><div><strong>${t.name}</strong><p>${t.desc}</p></div><button data-contract="${s.caseId}:${t.id}" ${ok&&!done?'':'disabled'}>${done?'✓ Pago':ok?'Resgatar +'+t.reward:'+'+t.reward+' ◈'}</button></div>`}).join('')}</div>`}
function contractsPage(){return `<section class="section officePage"><button class="backBtn" data-view="office">← Voltar à sede</button><div class="eyebrow">Livro de contratos</div><h2>Trabalhos do Instituto</h2><p>${keys.length*CONTRACTS.length} contratos independentes. Cada um paga uma única vez. Os objetivos são cumpridos durante os próprios casos.</p>${keys.map(id=>`<div class="contractArchive"><h3>${CASES[id].number} · ${CASES[id].short}</h3>${CONTRACTS.map(t=>{const state=fCase(id),ok=t.valid(state),done=claimed(id,t.id);return `<div class="contractCard"><div><strong>${t.name}</strong><p>${t.desc}</p></div><button data-contract="${id}:${t.id}" ${ok&&!done?'':'disabled'}>${done?'✓ Pago':ok?'+'+t.reward+' ◈':'Pendente'}</button></div>`}).join('')}</div>`).join('')}</section>`}
function saveWallet(){try{localStorage.setItem(K,JSON.stringify(saved))}catch(e){}}
function buyGear(id){const g=GEAR[id];if(!g)return;if(g.type==='permanent'&&own(id)){toast('Equipamento já adquirido.');return}if(saved.wallet<g.price){toast('Créditos insuficientes. Conclua missões para ganhar mais.');return}saved.wallet-=g.price;playEffect('buy');
 if(g.type==='permanent')saved.owned.push(id);else saved.stock[id]=charges(id)+1;
 saveWallet();toast('Adquirido: '+g.name+'!');render();}
const stable=id=>({...(saved.cases?.[id]||{})});
const completed=id=>Boolean(saved.completions?.[id]||saved.cases?.[id]?.outcome||saved.histories?.[id]?.outcome||(s&&s.caseId===id&&s.outcome));
const previousOutcome=id=>saved.histories?.[id]?.outcome||saved.cases?.[id]?.outcome||(s&&s.caseId===id?s.outcome:null);
const eligible=id=>!CASES[id]?.prerequisite||completed(CASES[id].prerequisite);
const difficulty=id=>CASES[id].difficulty||'Intermediário';
const requiredClues=()=>Math.min(9,(c().minClues||5)+(net.mode==='coop'&&net.inGame?Math.floor((net.size-1)/2):0));
const sequelOf=id=>Object.keys(CASES).find(x=>CASES[x].prerequisite===id);
const remoteEligible=id=>!CASES[id]?.prerequisite||net.mode==='solo'||net.players.filter(x=>x&&x.connected).every(p=>p.completed?.includes(CASES[id].prerequisite));
const totalCompleted=()=>keys.filter(id=>completed(id)).length;
const priorText=()=>{const prev=c().prerequisite, outcome=prev&&previousOutcome(prev);return outcome?(c().priorFlavor?.[outcome]||'Sua decisão anterior mudou a região.') :'';};
const hydrate=id=>{let b=blank(id),a=stable(id);return {...b,...a,caseId:id,view:'title',modal:null,reply:null,evidence:Array.isArray(a.evidence)?a.evidence.filter(k=>Object.hasOwn(CASES[id].clues,k)):[],witness:Array.isArray(a.witness)?a.witness.filter(k=>Object.hasOwn(CASES[id].witness.questions,k)):[],puzzleInput:[],boardPairs:[],boardChoice:null,boardSolved:Boolean(a.boardSolved),boardMistakes:Number(a.boardMistakes)||0,gearFlags:{...(a.gearFlags||{})},powdered:Array.isArray(a.powdered)?a.powdered:[],powderUses:Number(a.powderUses)||0,officeFlags:{...(a.officeFlags||{})},extraFlags:{...(a.extraFlags||{})},roleContributions:{...(a.roleContributions||{})}}};
let s=hydrate(CASES[saved.current]?saved.current:'lago');const c=()=>CASES[s.caseId];
const net={mode:'solo',role:'solo',slot:0,playerId:'p0',room:'',peer:null,conn:null,conns:{},size:2,online:false,inGame:false,name:'Pesquisador',players:[],specialty:'analyst',votes:{},theoryVotes:{},firstFinish:null,status:'',voteRounds:{theory:0,end:0},remoteCompleted:[],partnerRooms:{}};
const isMulti=()=>net.mode!=='solo';

const PARTY_ROLES=[
 {id:'analyst',name:'Analista',symbol:'⌕',ability:'Compara vestígios e amostras materiais.'},
 {id:'sensitive',name:'Sensitivo',symbol:'✧',ability:'Detecta ecos e manifestações do outro lado.'},
 {id:'archivist',name:'Arquivista',symbol:'▤',ability:'Identifica padrões em registros e símbolos.'},
 {id:'diplomat',name:'Diplomata',symbol:'♢',ability:'Interpreta intenções e contradições das testemunhas.'},
 {id:'tracker',name:'Rastreador',symbol:'✦',ability:'Reconstrói trajetórias e alterações ambientais.'}
];
const roleAt=slot=>PARTY_ROLES[Math.max(0,Math.min(4,slot))];
const connectedPlayers=()=>net.players.filter(p=>p&&p.connected);
const partyReady=()=>net.role==='host'&&connectedPlayers().length===net.size;
const clueOwner=(id,clue)=>{const all=Object.keys(CASES[id].clues),idx=all.indexOf(clue);if(idx<0)return -1;let owner=idx%net.size;const active=connectedPlayers().map(p=>p.slot);if(net.inGame&&active.length&&!active.includes(owner))owner=active[idx%active.length];return owner;};
const specialistRequired=()=>Math.min(connectedPlayers().length,Math.max(2,Math.floor(net.size/2)+1));
const specialistCount=()=>connectedPlayers().filter(p=>s.roleContributions?.['p'+p.slot]).length;
const specialistCanDo=()=>net.mode!=='coop'||!net.inGame||specialistCount()>=specialistRequired();
const myRoleClues=()=>Object.keys(c().clues).filter(id=>clueOwner(s.caseId,id)===net.slot);
const myRoleClueFound=()=>myRoleClues().find(id=>s.evidence.includes(id));
const playerName=pid=>net.players.find(p=>p&&'p'+p.slot===pid)?.name||'Pesquisador';
const playerRoster=()=>net.players.filter(x=>x).map(p=>`<div class="partyMember ${p.connected?'':'partyOffline'}"><span class="roleSig">${roleAt(p.slot).symbol}</span><div><b>${esc(p.name)}</b><small>${esc(roleAt(p.slot).name)}${p.slot===net.hostSlot?' · Coordenação':''}${p.connected?'':' · desconectado'}</small></div>${p.connected?'<span class="memberOnline">●</span>':'○'}</div>`).join('');
const roleReport=()=>{if(net.mode!=='coop'||!net.inGame)return '';const mine=myRoleClueFound();const done=!!s.roleContributions?.[net.playerId];return `<div class="roleMission"><div class="eyebrow">Sua tarefa de equipe · ${roleAt(net.slot).name}</div><h3>${roleAt(net.slot).symbol} Parecer de especialidade</h3><p>${esc(roleAt(net.slot).ability)} ${mine?'Você pode apresentar sua avaliação de '+c().clues[mine].name+'.':'Investigue ao menos um indício reservado à sua função para elaborar seu parecer.'}</p>${done?`<div class="roleSuccess">✓ Parecer enviado: ${esc(s.roleContributions[net.playerId])}</div>`:`<button class="btn outline" data-action="role-report" ${mine?'':'disabled'}>Registrar parecer para o grupo →</button>`}<small>${specialistCount()}/${specialistRequired()} pareceres necessários para concluir a dedução neste grupo de ${net.size}.</small></div>`};
const groupVotes=type=>{const votes=type==='theory'?net.theoryVotes:net.votes;const n=connectedPlayers().length;return `<div class="voteLedger"><b>Votação de ${n} jogadores</b>${connectedPlayers().map(p=>`<div>${roleAt(p.slot).symbol} ${esc(p.name)} <span>${votes['p'+p.slot]?'✓ Votou':'○ Pendente'}</span></div>`).join('')}<small>Maioria absoluta após todos votarem; empate exige outra rodada. ${net.voteRounds[type]?'Rodada '+(net.voteRounds[type]+1):''}</small></div>`};
function roleReportAction(){if(net.mode!=='coop'||!net.inGame||s.outcome)return;const clue=myRoleClueFound();if(!clue){toast('Você precisa identificar uma pista de sua função.');return}if(!s.roleContributions)s.roleContributions={};if(s.roleContributions[net.playerId])return;const e=c().clues[clue];s.roleContributions[net.playerId]=roleAt(net.slot).name+': '+e.insight;persist();toast('Seu parecer foi adicionado à investigação compartilhada.');render()}
function sendTo(conn,m){try{if(conn?.open)conn.send(m)}catch(e){}}
function broadcast(m){if(net.role!=='host')return;Object.values(net.conns).forEach(conn=>sendTo(conn,m));}
function publicRoster(){return net.players.filter(Boolean).map(p=>({slot:p.slot,name:p.name,connected:!!p.connected,completed:p.completed||[],score:p.score||0,finished:!!p.finished,rooms:p.rooms||{}}))}
function shareRoster(){if(net.role!=='host')return;const m={type:'lobby',size:net.size,mode:net.mode,inGame:net.inGame,players:publicRoster(),firstFinish:net.firstFinish};broadcast(m);render()}
function sendScoreboard(){if(net.role!=='host')return;broadcast({type:'scoreboard',players:publicRoster(),firstFinish:net.firstFinish})}
function rankTable(){const players=net.players.filter(Boolean).slice().sort((a,b)=>(b.score||0)-(a.score||0));return `<div class="rankTable">${players.map((p,i)=>`<div><span>${i+1}º · ${esc(p.name)}${p.slot===net.slot?' (você)':''}</span><b>${p.score||0} pts ${p.finished?'✓':''}</b></div>`).join('')}</div>`}

const sound={ctx:null,playing:false};
function ambientStop(){if(!sound.playing)return;try{sound.ctx?.close()}catch(e){}sound.playing=false;sound.ctx=null}
function soundtrackPreset(){return {gothic:[98,146.83,196],mist:[130.81,174.61,261.62],astral:[110,164.81,220]}[saved.soundtrack]||[98,146.83,196]}
function ambientToggle(){if(sound.playing){ambientStop();toast('Som ambiente desligado.');render();return}try{
 const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('Sem áudio');const ctx=new AC(),master=ctx.createGain();master.gain.value=.024;master.connect(ctx.destination);
 soundtrackPreset().forEach((freq,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type=['sine','triangle','sine'][i];o.frequency.value=freq;g.gain.value=[.52,.25,.14][i];o.connect(g);g.connect(master);o.start()});
 const lfo=ctx.createOscillator(),mod=ctx.createGain();lfo.type='sine';lfo.frequency.value=.072;mod.gain.value=.008;lfo.connect(mod);mod.connect(master.gain);lfo.start();
 const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=470;
 const buffer=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),samples=buffer.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=(Math.random()*2-1)*.28;
 const wind=ctx.createBufferSource(),w=ctx.createGain();wind.buffer=buffer;wind.loop=true;w.gain.value=.028;wind.connect(filter);filter.connect(w);w.connect(master);wind.start();
 sound.ctx=ctx;sound.playing=true;toast('Trilha original ligada · volume suave.');render();
 }catch(e){toast('O áudio não está disponível neste navegador.')}}
function playEffect(kind='find'){if(!sound.playing||!sound.ctx)return;try{const ctx=sound.ctx,at=ctx.currentTime,osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=kind==='danger'?'sawtooth':'sine';let f=kind==='reveal'?660:kind==='buy'?440:kind==='danger'?145:523;osc.frequency.setValueAtTime(f,at);osc.frequency.exponentialRampToValueAtTime(Math.max(80,f*(kind==='reveal'?1.5:.8)),at+.17);gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(.018,at+.015);gain.gain.exponentialRampToValueAtTime(.0001,at+.27);osc.connect(gain);gain.connect(ctx.destination);osc.start(at);osc.stop(at+.29)}catch(e){}}
function changeSoundtrack(){const order=['gothic','mist','astral'];saved.soundtrack=order[(order.indexOf(saved.soundtrack)+1)%order.length];saveWallet();if(sound.playing){ambientStop();ambientToggle()}else render()}
const modeLabel=()=>net.mode==='coop'?'Cooperativo':'Competitivo';
const score=()=>s.evidence.length*8+s.witness.length*10+(s.puzzleSolved?25:0)+(s.boardSolved?35:0)-Math.min(24,(s.boardMistakes||0)*4)+(s.interlude?10:0)+(gearOn('lens')?14:0)+(gearOn('recorder')?12:0)+(gearOn('amulet')?8:0)+(gearOn('ward')?12:0)-(gearOn('compass')?15:0)-(gearOn('pendulum')?6:0)+(gearOn('camera')?6:0)+(gearOn('incense')?4:0)+(gearOn('lantern')?3:0)+(s.theory===c().correct?75:0)+(s.outcome?c().outcomes[s.outcome].points:0)+(net.firstFinish===net.playerId?20:0);
function persist(announce=true){
 recordMoney();
 if(s.outcome){if(net.role==='host'&&net.players[0]&&!net.players[0].completed.includes(s.caseId))net.players[0].completed.push(s.caseId);saved.completions[s.caseId]=true;saved.histories[s.caseId]={outcome:s.outcome, theory:s.theory, date:new Date().toISOString(),boardSolved:!!s.boardSolved};}
 saved.cases[s.caseId]={...s,modal:null,reply:null,view:'title',puzzleInput:[]};saved.current=s.caseId;
 try{localStorage.setItem(K,JSON.stringify(saved))}catch(e){}
 if(announce&&isMulti()){sendProgress();if(s.outcome)send({type:'completed',id:s.caseId})}
}
function move(view){if(view==='shop')s.shopReturn=s.view;if(view==='office')s.officeFromMission=Boolean(net.inGame||app.querySelector('.bottomNav'));if(['collection','title','room','camp'].includes(view))s.officeFromMission=false;s.view=view;s.modal=null;s.reply=null;persist();render();try{window.scrollTo({top:0,behavior:'instant'})}catch(e){window.scrollTo(0,0)}}
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.appendChild(el);setTimeout(()=>el.remove(),3100)}
function send(m){if(net.role==='host')broadcast(m);else sendTo(net.conn,m)}
function sendProgress(){if(!net.inGame)return;const m={type:'progress',caseId:s.caseId,from:net.playerId,evidence:net.mode==='coop'?s.evidence:[],witness:net.mode==='coop'?s.witness:[],puzzleSolved:net.mode==='coop'&&s.puzzleSolved,boardSolved:net.mode==='coop'&&s.boardSolved,roleContributions:net.mode==='coop'?s.roleContributions:{},gearFlags:net.mode==='coop'?Object.fromEntries(Object.keys(s.gearFlags||{}).filter(k=>gearOn(k)).map(k=>[k,true])):{},score:score(),completed:!!s.outcome,outcome:s.outcome,rooms:{...saved.rooms}};if(net.role==='host'){const me=net.players[0];if(me){me.score=m.score;me.finished=m.completed;me.rooms={...saved.rooms}}broadcast(m);sendScoreboard()}else send(m)}
function closeNet(){ambientStop();try{Object.values(net.conns).forEach(conn=>conn.close());net.conn?.close();net.peer?.destroy()}catch(e){}Object.assign(net,{mode:'solo',role:'solo',slot:0,playerId:'p0',room:'',peer:null,conn:null,conns:{},size:2,online:false,inGame:false,players:[],specialty:'analyst',votes:{},theoryVotes:{},firstFinish:null,voteRounds:{theory:0,end:0},status:'',remoteCompleted:[],partnerRooms:{}})}
function setupCase(id,isNew=false){if(!CASES[id]||!eligible(id)){toast('Conclua primeiro o arquivo anterior para desbloquear.');return}s=isNew?blank(id):hydrate(id);s.trust=trustNow();s.view='brief';net.votes={};net.theoryVotes={};net.voteRounds={theory:0,end:0};net.firstFinish=null;if(net.role==='host'){net.players.forEach(p=>{if(p){p.score=0;p.finished=false}})}persist(false);render()}
function newMultiplayerCase(id){if(net.role!=='host'||!partyReady()){toast('A sala deve ter todos os participantes conectados.');return}if(!eligible(id)||!remoteEligible(id)){toast('Todos precisam ter concluído o arquivo anterior para liberar esta continuação.');return}net.inGame=true;setupCase(id,true);broadcast({type:'start',caseId:id,mode:net.mode,size:net.size,players:publicRoster()});shareRoster();toast('Arquivo sincronizado para '+net.size+' jogadores!')}
function trouble(err){net.status=err?.type==='unavailable-id'?'Esse código já está em uso.':'Erro na conexão: '+(err?.message||'Confira sua rede.');render();toast(net.status)}
function makeRoom(){if(typeof Peer==='undefined'){toast('A biblioteca online não carregou. Verifique a internet.');return}const mode=document.getElementById('modeChoice')?.value||'coop',name=(document.getElementById('playerName')?.value||'Pesquisador 1').trim().slice(0,24),id=document.getElementById('caseChoice')?.value||'lago',size=Math.min(5,Math.max(2,Number(document.getElementById('partySize')?.value)||2));if(!eligible(id)){toast('Primeiro conclua o caso original.');return}closeNet();Object.assign(net,{mode,role:'host',slot:0,playerId:'p0',name:name||'Pesquisador 1',size,room:Math.random().toString(36).slice(2,8).toUpperCase(),caseId:id,specialty:'analyst',status:'Abrindo sala…',players:[{slot:0,name:name||'Pesquisador 1',connected:true,score:0,completed:keys.filter(completed),rooms:{...saved.rooms}}],conns:{}});s.view='room';render();net.peer=new Peer('manual-criaturas-vol1-'+net.room.toLowerCase(),{debug:0});net.peer.on('open',()=>{net.online=true;net.status='Sala aberta. Aguardando pesquisadores.';render()});net.peer.on('connection',conn=>{if(connectedPlayers().length>=net.size){conn.on('open',()=>sendTo(conn,{type:'full'}));return}wire(conn)});net.peer.on('error',trouble)}
function enterRoom(){if(typeof Peer==='undefined'){toast('Biblioteca online indisponível.');return}const code=(document.getElementById('roomCode')?.value||'').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,6);if(code.length!==6){toast('O código precisa de 6 caracteres.');return}const name=(document.getElementById('playerName')?.value||'Pesquisador').trim().slice(0,24);closeNet();Object.assign(net,{mode:'coop',role:'guest',slot:-1,playerId:'pending',name:name||'Pesquisador',room:code,status:'Conectando à sala…'});s.view='room';render();net.peer=new Peer({debug:0});net.peer.on('open',()=>{net.conn=net.peer.connect('manual-criaturas-vol1-'+code.toLowerCase(),{reliable:true,serialization:'json'});wire(net.conn)});net.peer.on('error',trouble)}
function wire(conn){conn.on('open',()=>{net.online=true;if(net.role==='guest'){send({type:'hello',name:net.name,completed:keys.filter(completed),rooms:{...saved.rooms}});net.status='Aguardando atribuição de função…'}else net.status='Um pesquisador se conectou.';render()});conn.on('data',m=>receive(m,conn));conn.on('close',()=>{if(net.role==='host'){const slot=conn._slot;if(slot!=null){delete net.conns[slot];const p=net.players[slot];if(p){p.connected=false;if(!net.inGame)net.players[slot]=null};shareRoster();toast('Um participante desconectou.');}}else{net.online=false;net.status='Conexão interrompida. Volte à sala para tentar novamente.';toast(net.status);render()}});conn.on('error',trouble)}
function receive(m,conn){if(!m||typeof m!=='object')return;
 if(m.type==='full'){net.status='Sala cheia. Tente outra sala.';toast(net.status);render();return}
 if(m.type==='hello'&&net.role==='host'){
   if(conn._slot!=null)return;const slot=Array.from({length:net.size-1},(_,i)=>i+1).find(i=>!net.players[i]||!net.players[i].connected);
   if(slot==null){sendTo(conn,{type:'full'});conn.close();return}
   conn._slot=slot;net.conns[slot]=conn;net.players[slot]={slot,name:String(m.name||'Pesquisador '+(slot+1)).slice(0,24),connected:true,completed:Array.isArray(m.completed)?m.completed.filter(id=>CASES[id]):[],rooms:m.rooms||{},score:0,finished:false};
   sendTo(conn,{type:'assign',slot,size:net.size,mode:net.mode,players:publicRoster(),caseId:net.caseId,inGame:net.inGame,firstFinish:net.firstFinish});shareRoster();
   if(net.inGame)sendTo(conn,{type:'start',caseId:s.caseId,mode:net.mode,size:net.size,players:publicRoster(),resume:true,teamState:net.mode==='coop'?teamState():null});return;
 }
 if(m.type==='assign'&&net.role==='guest'){net.slot=m.slot;net.playerId='p'+m.slot;net.size=m.size;net.mode=m.mode;net.specialty=roleAt(net.slot).id;net.players=m.players||[];net.inGame=!!m.inGame;net.firstFinish=m.firstFinish||null;net.status='Você é '+roleAt(net.slot).name+' · aguardando início.';render();return}
 if(m.type==='lobby'&&net.role==='guest'){net.players=m.players||[];net.size=m.size||net.size;net.mode=m.mode||net.mode;net.inGame=!!m.inGame;net.firstFinish=m.firstFinish||net.firstFinish;render();return}
 if(m.type==='start'&&net.role==='guest'&&CASES[m.caseId]){
   if(!eligible(m.caseId)){send({type:'locked',caseId:m.caseId,parent:CASES[m.caseId].prerequisite});net.status='Arquivo bloqueado: conclua o anterior.';s.view='room';render();return}
   net.mode=m.mode;net.size=m.size;net.inGame=true;net.players=m.players||net.players;net.specialty=roleAt(net.slot).id;setupCase(m.caseId,true);
   if(m.teamState&&net.mode==='coop')mergeTeam(m.teamState);if(m.resume){s.theory=m.teamState?.theory||s.theory;s.outcome=m.teamState?.outcome||s.outcome;s.view=s.outcome?'ending':s.theory?'confrontation':'hub';persist(false);render()}toast('Caso sincronizado: '+c().short+' · '+net.size+' jogadores');return;
 }
 if(m.type==='locked'&&net.role==='host'){toast('Um dos participantes precisa concluir '+(CASES[m.parent]?.short||'o arquivo anterior')+'.');return}
 if(m.type==='completed'&&CASES[m.id]){if(net.role==='host'&&conn?._slot!=null){const p=net.players[conn._slot];if(p&&!p.completed.includes(m.id))p.completed.push(m.id);shareRoster()}return}
 if(m.type==='scoreboard'){net.players=m.players||net.players;net.firstFinish=m.firstFinish||null;render();return}
 if(m.type==='first'){net.firstFinish=m.winner;sendProgress();render();return}
 if(m.caseId&&m.caseId!==s.caseId)return;
 if(m.type==='progress'&&net.inGame){
   if(net.role==='host'&&conn?._slot!=null){const p=net.players[conn._slot];if(!p)return;p.score=Number(m.score)||0;p.finished=!!m.completed;p.rooms=m.rooms||p.rooms||{};
      if(net.mode==='versus'&&p.finished&&!net.firstFinish){net.firstFinish='p'+p.slot;broadcast({type:'first',winner:net.firstFinish})}
   }
   if(net.mode==='coop'){const changed=mergeTeam(m);if(changed){persist(false);render()};if(net.role==='host'){broadcast({type:'team',caseId:s.caseId,teamState:teamState()});sendScoreboard()}}
   else if(net.role==='host'){sendScoreboard();render()}return;
 }
 if(m.type==='team'&&net.role==='guest'&&net.mode==='coop'){if(mergeTeam(m.teamState)){persist(false);render()}return}
 if(m.type==='theory-vote'||m.type==='end-vote'){
    if(net.role!=='host'||net.mode!=='coop'||conn?._slot==null)return;const type=m.type==='theory-vote'?'theory':'end',valid=type==='theory'?Object.hasOwn(c().theories,m.choice):Object.hasOwn(c().outcomes,m.choice);
    if(!valid)return;(type==='theory'?net.theoryVotes:net.votes)['p'+conn._slot]=m.choice;resolveVote(type);return;
 }
 if(m.type==='vote-state'&&net.role==='guest'){net[m.voteType==='theory'?'theoryVotes':'votes']=m.votes||{};net.voteRounds[m.voteType]=m.round||0;render();return}
 if(m.type==='vote-reset'&&net.role==='guest'){net[m.voteType==='theory'?'theoryVotes':'votes']={};net.voteRounds[m.voteType]=m.round;toast('Sem maioria. Nova rodada!');render();return}
 if(m.type==='theory-decided'&&Object.hasOwn(c().theories,m.choice)){s.theory=m.choice;s.selectedTheory=m.choice;net.theoryVotes={};move('confrontation');return}
 if(m.type==='end-decided'&&Object.hasOwn(c().outcomes,m.choice)){s.outcome=m.choice;s.dailyOutcomeDate=localDay();net.votes={};move('ending');return}
}
function teamState(){return {caseId:s.caseId,evidence:s.evidence,witness:s.witness,puzzleSolved:s.puzzleSolved,boardSolved:s.boardSolved,roleContributions:s.roleContributions||{},gearFlags:s.gearFlags||{},theory:s.theory,outcome:s.outcome}}
function mergeTeam(m){if(!m||m.caseId&&m.caseId!==s.caseId)return false;const before=JSON.stringify(teamState());for(const id of m.evidence||[])if(Object.hasOwn(c().clues,id)&&!s.evidence.includes(id))s.evidence.push(id);for(const id of m.witness||[])if(Object.hasOwn(c().witness.questions,id)&&!s.witness.includes(id))s.witness.push(id);s.puzzleSolved=!!s.puzzleSolved||!!m.puzzleSolved;s.boardSolved=!!s.boardSolved||!!m.boardSolved;s.roleContributions={...(s.roleContributions||{}),...(m.roleContributions||{})};if(net.mode==='coop')for(const [id,value] of Object.entries(m.gearFlags||{}))if(value)s.gearFlags[id]=true;s.trust=trustNow();return JSON.stringify(teamState())!==before}
function resolveVote(type){if(net.role!=='host'||net.mode!=='coop')return;const votes=type==='theory'?net.theoryVotes:net.votes;const active=connectedPlayers();broadcast({type:'vote-state',voteType:type,votes:{...votes},round:net.voteRounds[type]});if(!active.every(p=>votes['p'+p.slot])){render();return}const freq={};active.forEach(p=>{const choice=votes['p'+p.slot];freq[choice]=(freq[choice]||0)+1});const winner=Object.entries(freq).find(([k,n])=>n>active.length/2)?.[0];if(!winner){net.voteRounds[type]++;if(type==='theory')net.theoryVotes={};else net.votes={};broadcast({type:'vote-reset',voteType:type,round:net.voteRounds[type]});toast('Votos divididos. Conversem e votem novamente.');render();return}if(type==='theory'){if(!specialistCanDo()){toast('Faltam pareceres dos especialistas.');return}s.theory=winner;s.selectedTheory=winner;net.theoryVotes={};broadcast({type:'theory-decided',choice:winner});move('confrontation')}else{if(!canDo(c().outcomes[winner]?.needs)){net.votes={};broadcast({type:'vote-reset',voteType:type,round:++net.voteRounds[type]});toast('A decisão vencedora exige mais evidências.');render();return}s.outcome=winner;s.dailyOutcomeDate=localDay();net.votes={};broadcast({type:'end-decided',choice:winner});move('ending')}}
function voteTheory(){if(s.evidence.length<requiredClues()||!s.selectedTheory)return;if(net.inGame&&net.mode==='coop'){if(!specialistCanDo()){toast('Registrem mais pareceres de especialidade antes da votação.');return}net.theoryVotes[net.playerId]=s.selectedTheory;if(net.role==='host')resolveVote('theory');else send({type:'theory-vote',caseId:s.caseId,choice:s.selectedTheory});render();toast('Voto enviado. Aguardando o grupo.');return}s.theory=s.selectedTheory;move('confrontation')}
function voteEnd(id){if(!canDo(c().outcomes[id].needs))return;if(net.inGame&&net.mode==='coop'){net.votes[net.playerId]=id;if(net.role==='host')resolveVote('end');else send({type:'end-vote',caseId:s.caseId,choice:id});render();toast('Voto registrado. Aguardando o grupo.');return}s.outcome=id;s.dailyOutcomeDate=localDay();move('ending');if(net.inGame&&net.mode==='versus'){if(net.role==='host'&&!net.firstFinish){net.firstFinish=net.playerId;broadcast({type:'first',winner:net.playerId})}sendProgress()}}
function canDo(req={}){return (!req.correct||s.theory===c().correct)&&(!req.trust||s.trust>=req.trust+(c().prerequisite&&previousOutcome(c().prerequisite)==='selar'?1:0))&&(!req.puzzle||s.puzzleSolved)&&(req.clues||[]).every(x=>s.evidence.includes(x))&&(req.witness||[]).every(x=>s.witness.includes(x))}
function nav(){return `<nav class="bottomNav" aria-label="Menu do jogo">${[['hub','♧','Mapa'],['dossier','⌕','Pistas'],['theory','◈','Teorias'],['office','♜','Sede'],['bestiary','▤','Bestiário']].map(([id,ico,label])=>`<button class="navButton ${s.view===id||id==='hub'&&s.view==='scene'?'active':''}" data-view="${id}"><span class="navGlyph">${ico}</span><span>${label}</span></button>`).join('')}</nav>`}
function ribbon(){if(!isMulti())return '';return `<div class="multiRibbon"><div><span class="miniAccent">${modeLabel()} · ${net.size} jogadores · ${esc(net.room)}</span><span class="muted">${connectedPlayers().length}/${net.size} online · ${roleAt(Math.max(0,net.slot)).symbol} ${esc(roleAt(Math.max(0,net.slot)).name)}</span></div>${net.mode==='versus'?rankTable():`<span class="teamProgress">${specialistCount()}/${specialistRequired()} pareceres · ${s.evidence.length}/9 pistas</span>`}</div>`}
function header(){return `${ribbon()}<header class="appTop"><button class="markLink" data-view="collection"><div class="mark">M<span style="font-size:12px">✦</span>C</div><div class="markSub">Manual das Criaturas</div></button><div class="headActions"><button class="soundQuick" data-action="audio" aria-label="Alternar trilha sonora">${sound.playing?'♫':'♪'}</button><div class="countPill">${saved.wallet} ◈ · ${s.evidence.length}/9</div></div></header>`}
function collection(){let cards='';for(const level of LEVELS){const list=keys.filter(id=>difficulty(id)===level);cards+=`<div class="levelSection"><div class="levelHeading"><div class="eyebrow">NÍVEL DE PESQUISA</div><h2>${level}</h2><p>${level==='Iniciante'?'4 pistas para uma dedução · introdução ao Instituto':level==='Intermediário'?'5 pistas · diferentes leituras e decisões':'6–7 pistas · teorias mais exigentes e consequências complexas'}</p></div>`;for(const id of list){const cc=CASES[id],done=completed(id),unlocked=eligible(id),remoteOk=remoteEligible(id),parent=cc.prerequisite&&CASES[cc.prerequisite],isSequel=!!parent;cards+=`<button class="caseSelect ${unlocked?'':'lockedArchive'}" data-case="${id}" ${(!unlocked||net.online&&(net.role==='guest'||!remoteOk))?'disabled':''}><div class="caseCover"><img src="${cc.image}" alt="Cenário de ${esc(cc.short)}" loading="lazy"/><span class="caseNumber">ARQUIVO ${cc.number}${isSequel?' · PARTE II':''}</span></div><div class="caseSelectText"><div class="eyebrow">${cc.type}</div><strong>${cc.short}</strong><p>${cc.subtitle}</p><div class="caseDifficulty">${isSequel?'↳ Continuação de '+parent.short+' · ':''}${Math.min(9,cc.minClues+(net.mode==='coop'&&net.inGame?Math.floor((net.size-1)/2):0))} pistas mínimas</div><div class="caseStatus">${done?'✓ Concluído · rever investigação':!unlocked?'◈ Bloqueado · conclua o arquivo '+parent.number:!remoteOk?'◈ Sua equipe ainda precisa concluir o anterior':'✦ Investigar agora'} →</div></div></button>`;}cards+='</div>';}return `<section class="archiveHero"><div class="archiveStars">✦ · INSTITUTO DE ESTUDOS DO VÉU · ✦</div><h1>Manual<br>das Criaturas</h1><p>Quatorze arquivos e uma nova investigação. Cada decisão deixa um rastro.</p><div class="archiveCount">${totalCompleted()} / ${keys.length} ARQUIVOS CONCLUÍDOS · VOLUMES I E II</div><div class="worldReport"><div><span>Confiança das criaturas</span><b>${worldStats().trust}%</b></div><div class="worldMeter"><i style="width:${worldStats().trust}%"></i></div><div><span>Estabilidade do Véu</span><b>${worldStats().veil}%</b></div><div class="worldMeter"><i style="width:${worldStats().veil}%"></i></div><small>${worldStats().research} registros de conhecimento · suas decisões atravessam os casos</small></div></section><section class="section caseSelector"><button class="officePromo" data-view="office"><span>♜ SUA SEDE</span><strong>Amplie o Instituto</strong><small>${Object.keys(OFFICE_ROOMS).filter(hasRoom).length}/4 alas · contratos e recursos</small></button><button class="shopPromo" data-view="shop"><span>✧ ARSENAL DO INSTITUTO</span><strong>Loja de equipamento</strong><small>${saved.wallet} créditos ◈ · Compre antes de investigar</small></button>${cards}<div class="partDivider"><button class="btn outline" data-action="multiplayer">✦ Jogar online · 2 a 5 jogadores</button><div class="caption" style="margin-top:10px">Cooperativo ou competitivo, de 2 a 5 jogadores. Para abrir uma continuação, todos os aparelhos precisam ter concluído o caso anterior.</div></div></section>`}
function cover(){return `<section class="cover" style="--cover-image:url('${c().image}')"><div class="coverHead">INSTITUTO DE ESTUDOS DO VÉU · ARQUIVO ${c().number}</div><div class="coverInner"><img class="coverLogo" src="assets/emblema.svg" alt="Emblema do Instituto"/><div class="eyebrow">UMA INVESTIGAÇÃO SOBRENATURAL</div><h1 class="coverTitle">Manual<br>das Criaturas</h1><p class="coverCopy">${c().intro}</p><button class="btn" data-view="collection">Escolher investigação →</button><button class="btn outline" data-view="office" style="margin-top:12px">♜ Visitar minha sede →</button><button class="btn outline" data-view="shop" style="margin-top:12px">✧ Loja do Instituto · ${saved.wallet} ◈</button><button class="btn outline" data-action="multiplayer" style="margin-top:13px">✦ Jogar online · 2 a 5</button><button class="btn ghost" data-action="continue">Continuar arquivo ${c().number}</button><div class="coverBottom">QUATORZE ARQUIVOS · SETE HISTÓRIAS</div></div></section>`}
function roomMenu(){return `<section class="section roomPage"><button class="backBtn" data-view="collection">← Arquivos</button><div class="eyebrow">Instituto do Véu · investigação em equipe</div><h2>Até cinco pesquisadores.<br>Uma verdade.</h2><p>Joguem em 2, 3, 4 ou 5 celulares. No cooperativo, cada um terá pistas exclusivas e uma função. No competitivo, vocês disputam o melhor relatório.</p><label class="fieldLabel" for="playerName">Seu codinome</label><input id="playerName" class="fieldInput" maxlength="24" placeholder="Seu codinome" value="${esc(net.name==='Pesquisador'?'':net.name)}"/><label class="fieldLabel" for="partySize">Número de jogadores</label><select id="partySize" class="fieldInput"><option value="2">2 pesquisadores</option><option value="3">3 pesquisadores</option><option value="4">4 pesquisadores</option><option value="5">5 pesquisadores</option></select><label class="fieldLabel" for="modeChoice">Modo</label><select id="modeChoice" class="fieldInput"><option value="coop">✦ Cooperativo — pistas divididas e votação por maioria</option><option value="versus">⚔ Competitivo — investigação individual e ranking</option></select><label class="fieldLabel" for="caseChoice">Caso inicial</label><select id="caseChoice" class="fieldInput">${Object.entries(CASES).map(([id,cc])=>`<option value="${id}" ${!eligible(id)?'disabled':''}>${cc.number} · ${esc(cc.short)}${cc.prerequisite?' · CONTINUAÇÃO':''}</option>`).join('')}</select><button class="btn" data-action="host">Criar sala →</button><div class="orLine">OU ENTRE NA SALA DE SEUS AMIGOS</div><input id="roomCode" class="fieldInput codeInput" maxlength="6" autocomplete="off" autocapitalize="characters" placeholder="CÓDIGO" value="${esc(new URLSearchParams(location.search).get('room')||'')}"/><button class="btn outline" data-action="join">Entrar na sala →</button><div class="notice">A sala começa apenas quando todos os lugares estiverem ocupados. Requer internet e serviço PeerJS; para jogar de aparelhos diferentes, publique o arquivo HTML num endereço HTTPS.</div></section>`}
function room(){const link=location.protocol==='https:'?location.href.split('?')[0]+'?room='+net.room:null;return `<section class="section roomPage"><div class="eyebrow">Sala ${esc(net.room)} · ${modeLabel()}</div><h2>${connectedPlayers().length} / ${net.size} jogadores</h2><p>${esc(net.status)}</p><div class="roomCode">${esc(net.room)}</div><div class="partyRoster">${playerRoster()}</div>${net.role==='guest'&&net.slot<0?'<p>Esperando autorização do anfitrião…</p>':net.mode==='coop'?`<div class="notice">Sua especialidade: ${roleAt(net.slot).symbol} <b>${roleAt(net.slot).name}</b>. ${esc(roleAt(net.slot).ability)}</div>`:`<div class="notice">Competitivo: cada pessoa investiga todas as pistas. O ranking aparece durante e após o caso.</div>`}<button class="btn outline" data-action="copy-room">${link?'Copiar convite':'Copiar código'} →</button>${net.role==='host'?`<button class="btn" data-action="start-party" ${partyReady()&&remoteEligible(net.caseId)?'':'disabled'}>Iniciar caso com ${net.size} jogadores →</button>${!remoteEligible(net.caseId)?'<p class="caption">Um dos participantes ainda precisa concluir o caso anterior.</p>':''}`:'<div class="notice">O anfitrião inicia o caso quando o grupo estiver completo.</div>'}<button class="btn ghost" data-action="leave-room">Sair da sala</button></section>`}
function brief(){return `<div class="briefArt" style="background-image:linear-gradient(180deg,transparent,#091820),url('${c().image}')"><span class="stamp">CONFIDENCIAL · ${c().number}</span></div><section class="section"><div class="eyebrow">Dossiê ${c().number} · ${c().type}</div><h2>${c().title}</h2><p class="lead">${c().brief}</p><div class="briefQuote">${c().quote}</div>${c().prerequisite?`<div class="notice storyMemory"><strong>O que sua decisão anterior provocou</strong><p>${esc(priorText())}</p></div>`:''}${worldEcho()?`<div class="notice storyMemory"><strong>Rastro de outra investigação</strong><p>${esc(worldEchoText())}</p></div>`:''}<div class="datagrid"><div class="datum"><span class="micro">LOCAL</span><strong>${c().place}</strong></div><div class="datum"><span class="micro">RISCO</span><strong>${c().danger}</strong></div><div class="datum"><span class="micro">OCORRÊNCIA</span><strong>${c().victims}</strong></div><div class="datum"><span class="micro">OBJETIVO</span><strong>Investigar e decidir</strong></div></div><p>Examine os cenários, entreviste uma testemunha e apresente uma hipótese. Sua conclusão muda quais desfechos estarão disponíveis.</p><button class="btn outline" data-view="shop">✧ Equipar antes da missão · ${saved.wallet} ◈</button><button class="btn" data-action="begin">${c().ritual&&!s.ritualComplete?'Entrar na festa →':'Iniciar investigação →'}</button><button class="btn ghost" data-view="collection">← Escolher outro arquivo</button></section>`}
function ritual(){return `<div class="ritualHero"><div class="ritualOrb"></div><span>CONVITE IRREVOGÁVEL</span><strong>O Néctar<br>Prismático</strong></div><section class="section"><div class="eyebrow">Caso 002 · Cerimônia de entrada</div><h2>Para entrar, você precisa aceitar o ritual.</h2><p class="lead">Um porteiro sem olhos lhe entrega uma taça luminosa. A regra da festa é simples: todo convidado passa pelo rito e começa a enxergar dois salões ao mesmo tempo.</p><div class="briefQuote">“Não é para esquecer quem você é. É para lembrar quem nunca foi.”</div><p>Na história, o Néctar Prismático é uma substância mágica fictícia. Após o ritual, você pode alternar entre <strong>visão comum</strong> e <strong>visão prismática</strong> para investigar cenas que se transformam lentamente.</p><div class="notice">Experiência visual com movimentos suaves, sem flashes. Você pode reduzir os efeitos a qualquer momento.</div><button class="btn" data-action="ritual">✦ Aceitar o rito e entrar no baile</button><button class="btn ghost" data-view="collection">Recusar o convite e voltar aos arquivos</button></section>`}
function phaseControl(){if(!c().phaseNames)return '';return `<div class="phaseControl"><div><div class="eyebrow">${s.caseId==='baile'?'Percepção alterada':s.caseId==='vampiro'?'Filtro investigativo':s.caseId==='lobo'?'Rastros lunares':'Lente investigativa'}</div><span>${c().phaseText}</span>${s.caseId==='baile'?`<button class="effectsToggle" data-action="effects">${s.pretty?'◌ Desligar efeitos visuais':'✦ Ligar efeitos visuais'}</button>`:''}</div><button class="phaseButton" data-action="phase">${s.phase===0?'◐ '+c().phaseNames[1]+' →':'◑ '+c().phaseNames[0]+' →'}</button></div>`}
function hub(){return `<div class="caseBanner" style="background-image:url('${c().image}')"><div class="caseBannerText"><div class="eyebrow">Arquivo ${c().number} · Em andamento</div><h2>${c().short}</h2></div></div><section class="section"><div class="eyebrow">${c().place}</div><h3 style="margin:8px 0 10px">Escolha o local da investigação</h3><div class="progressTrack"><div class="progressFill" style="width:${s.evidence.length/9*100}%"></div></div><p class="caption">${s.evidence.length} de 9 indícios descobertos</p>${phaseControl()}${net.inGame&&net.mode==='coop'?`<div class="roleNotice"><b>${roleAt(net.slot).symbol} ${roleAt(net.slot).name}</b><p>${roleAt(net.slot).ability} Cada jogador examina indícios exclusivos; as descobertas são partilhadas com todo o grupo.</p></div>`:''}${roleReport()}${worldEcho()?`<div class="echoCard"><div class="eyebrow">Rastro de decisões passadas · ${CASES[rCase().link].short}</div><p>${esc(worldEchoText())}</p><button class="smallBtn" data-action="claim-echo" ${s.echoClaimed?'disabled':''}>${s.echoClaimed?'✓ Rastro já registrado':'Analisar ligação com o caso anterior (+1 pista)'}</button></div>`:''}${hasRoom('laboratory')||hasRoom('library')?officeTools():''}<div class="gearMini">${Object.entries(GEAR).filter(([id,g])=>g.type==='permanent'&&own(id)).map(([id,g])=>`<span>${g.icon} ${g.name}</span>`).join('')||'Nenhuma ferramenta adquirida'}<span>✴ ${charges('powder')} pó</span><span>⬡ ${charges('ward')} selos</span><span>♨ ${charges('incense')} incensos</span><span>✹ ${charges('lantern')} lanternas</span> · <button data-view="shop">Ver loja →</button></div><div class="cardList">${Object.entries(c().scenes).map(([id,loc])=>`<button class="locationCard" data-scene="${id}"><img src="${loc.image}" alt=""/><div><div class="cardTitle">${loc.name}</div><div class="cardSubtitle">${loc.subtitle}</div><div class="cardCount">${loc.items.filter(k=>s.evidence.includes(k)).length}/3 pistas</div></div></button>`).join('')}</div><div class="partDivider"><div class="eyebrow">Testemunha</div><button class="locationCard" data-view="witness"><img src="${c().witness.image}" alt="Retrato de ${c().witness.name}"/><div><div class="cardTitle">${c().witness.name}</div><div class="cardSubtitle">${c().witness.role}</div><div class="cardCount">${s.witness.length}/3 perguntas</div></div></button></div>${c().puzzle?`<div class="partDivider"><div class="notePaper"><div class="eyebrow">Desafio do baile</div><h3>Ritmo dos Espelhos</h3><p>Uma sequência de três cores pode desfazer a festa.</p><button class="btn outline" data-view="puzzle">${s.puzzleSolved?'✓ Ritmo resolvido':'Investigar o ritmo →'}</button></div></div>`:''}${s.caseId==='baile'?`<div class="partDivider"><div class="eyebrow">Experiências do baile</div><button class="btn outline" data-view="interlude">✧ ${s.interlude?'Rever encontro impossível':'Conversar com sua própria sombra'}</button><button class="btn ghost" data-action="audio">${sound.playing?'♫ Desligar som ambiente':'♫ Ligar som ambiente suave'}</button></div>`:''}<div class="partDivider"><div class="notePaper"><div class="eyebrow">Novo · Enigma interativo</div><h3>Quadro de provas</h3><p>${esc(rCase().question)}</p><button class="btn outline" data-view="board">${s.boardSolved?'✓ Conexão comprovada':'Conectar pistas e deduzir →'}</button></div></div><div class="partDivider"><div class="notePaper"><div class="eyebrow">Caderno de campo</div><h3>Uma boa teoria precisa de ${requiredClues()} pistas.</h3><p>Quanto mais pistas você descobrir, mais decisões terá no encontro final.</p><button class="btn outline" data-view="theory">Analisar hipóteses →</button></div></div>${isMulti()&&net.role==='host'?'<button class="btn ghost" data-view="collection">Escolher outro caso para a equipe</button>':''}</section>`}
function scene(){const loc=c().scenes[s.activeScene]||Object.values(c().scenes)[0];return `<div class="sceneIntro"><button class="backBtn" data-view="hub">← Voltar aos locais</button><div class="eyebrow">Investigação · Arquivo ${c().number}</div><h2>${loc.name}</h2><p>${loc.intro}</p></div>${phaseControl()}<div class="sceneFrame ${s.phase&&s.pretty?'phaseOn':''} ${s.caseId==='baile'&&s.pretty?'dreamFrame':''}"><img src="${loc.image}" alt="Ilustração de ${loc.name}" draggable="false"/>${s.caseId==='baile'&&s.pretty&&s.phase?'<div class="prismOverlay" aria-hidden="true"></div>':''}${loc.items.map(id=>{let e=c().clues[id],found=s.evidence.includes(id);if(e.phase!=null&&e.phase!==s.phase)return '';if(!canInspect(id)&&!found)return `<span class="hotspot roleLocked" style="left:${e.x}%;top:${e.y}%" title="Pista reservada a outro pesquisador">${roleAt(clueOwner(s.caseId,id)).symbol}</span>`;return `<button class="hotspot ${found?'found':''}" style="left:${e.x}%;top:${e.y}%" data-clue="${id}" aria-label="Examinar ${esc(e.name)}"><span>${found?'✓':'✦'}</span></button>`}).join('')}</div>${gearSceneTools()}<div class="sceneFoot"><p>Toque nos pontos luminosos. ${net.inGame&&net.mode==='coop'?'Os símbolos esmaecidos pertencem a outro pesquisador. ':''}${c().phaseNames?'Alterne a visão para revelar outros indícios.':''}</p><div class="sceneFooterRow"><button class="smallBtn" data-view="dossier">Ver pistas (${s.evidence.length})</button><button class="smallBtn" data-view="hub">Outros lugares →</button></div></div>`}
function witness(){let w=c().witness;let reply=s.reply?w.questions[s.reply]:null;return `<div class="portraitWrap" style="background-image:url('${w.image}')"><div class="portraitName">${w.name}<span class="micro"> · TESTEMUNHA</span></div></div><section class="section"><button class="backBtn" data-view="hub">← Voltar</button><div class="eyebrow">Depoimento · ${c().place}</div><p class="lead">${w.intro}</p>${reply?`<div class="reply"><strong>${w.name} responde</strong><p>${reply.answer}</p></div>`:`<div class="dialogue">“Você veio me escutar ou já decidiu no que acreditar?”</div>`}<div class="eyebrow">Perguntas disponíveis</div>${Object.entries(w.questions).map(([id,q],i)=>`<button class="option ${s.witness.includes(id)?'done':''}" data-question="${id}"><b>0${i+1}.</b><span>${q.q} ${s.witness.includes(id)?'✓':''}</span></button>`).join('')}<div class="equipmentActions"><div class="eyebrow">Investigar com gravador</div>${own('recorder')?`<button class="toolAction" data-gear="recorder" ${gearOn('recorder')||s.outcome?'disabled':''}>♫ ${gearOn('recorder')?'✓ Depoimento sobrenatural guardado':'Gravar pergunta secreta (+2 confiança)'}</button>${gearOn('recorder')?`<div class="secretRevelation">${esc(CASE_GEAR[s.caseId].recorder)}</div>`:''}`:`<button class="toolAction" data-view="shop">♫ Gravador de Ecos não adquirido · Loja →</button>`}</div>${charges('incense')||gearOn('incense')?`<div class="equipmentActions"><button class="toolAction" data-gear="incense" ${charges('incense')&&!gearOn('incense')&&!s.outcome?'':'disabled'}>♨ ${gearOn('incense')?'✓ Incenso utilizado':'Usar Incenso da Memória · +2 confiança ('+charges('incense')+' disponível)'}</button>${gearOn('incense')?`<p>${esc(FIELD_NOTES[s.caseId])}</p>`:''}</div>`:''}<p class="caption">Suas perguntas podem aumentar a confiança, permitindo negociar alguns desfechos.</p><button class="btn outline" data-view="hub">Concluir entrevista →</button></section>`}
function dossier(){return `<section class="section"><div class="eyebrow">Caderno de campo · Arquivo ${c().number}</div><h2>Evidências</h2><p>Compare as pistas e tente distinguir coincidências de consequências.</p><div class="notice">${s.evidence.length}/9 pistas encontradas · ${s.evidence.length>=requiredClues()?'Você já pode apresentar a hipótese.':'Encontre pelo menos '+requiredClues()+' para avançar.'}</div>${Object.values(c().scenes).map(loc=>`<div class="partDivider"><div class="eyebrow">${loc.name}</div>${loc.items.map((id,i)=>{let e=c().clues[id],found=s.evidence.includes(id);return found?`<button class="evidenceItem" data-clue="${id}"><div class="evidenceIndex">${i+1}</div><div class="evidenceText"><strong>${e.name}</strong><em>Revisar análise →</em></div></button>`:`<div class="evidenceItem undiscovered"><div class="emptyMark"></div><div class="evidenceText"><strong>Indício ainda desconhecido</strong><em>${loc.name}${e.phase!=null?' · uma das percepções':''}</em></div></div>`}).join('')}</div>`).join('')}${gearOn('lens')?`<div class="secretRevelation"><div class="eyebrow">◉ ASSINATURA ESPECTRAL · PISTA EXTRA</div>${esc(CASE_GEAR[s.caseId].lens)}</div>`:''}${gearOn('recorder')?`<div class="secretRevelation"><div class="eyebrow">♫ REGISTRO DE VOZ</div>${esc(CASE_GEAR[s.caseId].recorder)}</div>`:''}<button class="btn outline" data-view="board">${s.boardSolved?'✓ Quadro solucionado':'Conectar evidências no quadro →'}</button><button class="btn" data-view="theory">Organizar hipóteses →</button></section>`}
function theories(){return `<section class="section"><div class="eyebrow">Etapa 04 · Hipóteses</div><h2>Quem está por trás disso?</h2><p>O folclore confunde muitos fenômenos. Escolha a explicação que melhor corresponde às pistas.</p><div class="notice">${s.evidence.length}/9 pistas. ${s.evidence.length<requiredClues()?'Descubra ao menos '+requiredClues()+'.':'Pronto para registrar uma hipótese.'}${net.online&&net.mode==='coop'?`<p>Seu voto: ${net.theoryVotes[net.playerId]?c().theories[net.theoryVotes[net.playerId]].name:'pendente'} · ${Object.keys(net.theoryVotes).length}/${connectedPlayers().length} votos.</p>`:''}</div>${Object.entries(c().theories).map(([id,t])=>`<button class="theoryCard ${s.selectedTheory===id?'selected':''}" data-theory="${id}"><div class="theoryBadge">${t.kind}</div><strong>${t.name}${s.selectedTheory===id?' ✓':''}</strong><p>${t.desc}</p></button>`).join('')}${roleReport()}${net.mode==='coop'&&net.inGame?groupVotes('theory'):''}${s.boardSolved?`<div class="secretRevelation">✦ Prova cruzada confirmada: ${esc(rCase().conclusion)}</div>`:`<div class="notice">Existe uma ligação entre provas que ainda não foi demonstrada. <button class="smallBtn" data-view="board">Abrir quadro →</button></div>`}<div class="equipmentActions"><div class="eyebrow">Ferramenta de dedução</div>${own('compass')?`<button class="toolAction" data-gear="compass" ${gearOn('compass')||s.outcome?'disabled':''}>✧ ${gearOn('compass')?'✓ Bússola consultada':'Consultar Bússola Rúnica (-15 pontos)'}</button>${gearOn('compass')?`<div class="secretRevelation">${esc(CASE_GEAR[s.caseId].compass)}</div>`:''}`:`<button class="toolAction" data-view="shop">✧ Bússola Rúnica não adquirida · Loja →</button>`}</div><button class="btn" ${s.evidence.length<requiredClues()||!s.selectedTheory||!specialistCanDo()?'disabled':''} data-action="confirm">Confirmar hipótese →</button><button class="btn ghost" data-view="hub">Voltar à investigação</button></section>`}
function confrontation(){let right=s.theory===c().correct;return `<div class="revealPicture" style="background-image:url('${c().creatureImage}')"><div class="revealTitle">${c().revealTitle}</div></div><section class="section"><div class="eyebrow">Confronto · Arquivo ${c().number}</div><h2>${right?'Você desvendou o mistério.':'A verdade era outra.'}</h2><p class="lead">${c().reveal}</p><div class="briefQuote">${c().revealQuote}</div><p>${right?'Sua teoria estava correta. Suas evidências podem permitir uma solução melhor.':'Você escolheu uma hipótese incorreta. A entidade revela sua verdadeira natureza, mas algumas alternativas podem estar bloqueadas por falta de provas.'}</p>${net.online&&net.mode==='coop'?`<div class="notice"><b>Decisão em equipe:</b> cada jogador vota; a maioria decide após todos participarem.<p>Seu voto: ${net.votes[net.playerId]?c().outcomes[net.votes[net.playerId]].tag:'pendente'} · ${Object.keys(net.votes).length}/${connectedPlayers().length} votos.</p></div>`:''}<div class="equipmentActions"><div class="eyebrow">Preparação para a decisão final</div>${net.mode==='coop'&&net.inGame?groupVotes('end'):''}${own('amulet')?`<button class="toolAction" data-gear="amulet" ${gearOn('amulet')||s.outcome?'disabled':''}>❖ ${gearOn('amulet')?'✓ Pacto de trégua iniciado':'Propor trégua (+2 confiança)'}</button>${gearOn('amulet')?`<div class="secretRevelation">${esc(CASE_GEAR[s.caseId].amulet)}</div>`:''}`:`<button class="toolAction" data-view="shop">❖ Amuleto de Trégua não adquirido · Loja →</button>`}<button class="toolAction" data-gear="ward" ${charges('ward')&&!gearOn('ward')&&!s.outcome?'':'disabled'}>⬡ ${gearOn('ward')?'✓ Selo ativado':`Ativar Selo de Proteção (${charges('ward')} disponível)`}</button></div>${hasRoom('sanctuary')?`<div class="officeEvidence">⬡ Câmara de Salvaguarda: a proteção do Instituto aumenta a confiança e oferece um local seguro para negociações.</div>`:''}<div class="eyebrow">Destino da criatura</div>${Object.entries(c().outcomes).map(([id,o],i)=>{let enabled=canDo(o.needs);return `<button class="option endingOption" data-end="${id}" ${enabled?'':'disabled'}><b>${['✧','♢','⌁','◆'][i]}</b><span><strong class="gold">${o.label}</strong><br>${o.desc}<br><small class="muted">${enabled?'Possível com as provas reunidas.':o.unlock}</small></span></button>`}).join('')}<button class="btn ghost" data-view="theory">← Rever teoria</button></section>`}
function ending(){let o=c().outcomes[s.outcome]||c().outcomes.selar;return `<div class="endingHero" style="background-image:linear-gradient(0deg,#09151b,transparent),url('${c().creatureImage}')"><div class="endingTag">ARQUIVO ${c().number} · ENCERRADO</div></div><section class="section"><div class="eyebrow">${o.tag}</div><h2>${o.title}</h2>${c().prerequisite?`<div class="notice storyMemory">${esc(priorText())}</div>`:''}<p class="lead">${o.text}</p><p>${o.after}</p>${hasRoom('sanctuary')?`<div class="secretRevelation">⬡ A equipe leva os envolvidos à Câmara de Salvaguarda do Instituto, onde podem se recuperar longe de ameaças.</div>`:''}${gearOn('ward')?`<div class="secretRevelation"><div class="eyebrow">⬡ PROTEÇÃO ATIVADA</div>${esc(CASE_GEAR[s.caseId].ward)}</div>`:''}${gearOn('amulet')?`<p class="caption">O pacto feito com o Amuleto de Trégua influenciou a reação da criatura.</p>`:''}${s.boardSolved?`<div class="secretRevelation">Seu quadro de provas confirmou: ${esc(rCase().conclusion)}. Essa descoberta ficará registrada na memória do mundo.</div>`:''}<div class="orn">✦</div><div class="notice"><strong>Consequência</strong><p>${o.impact}</p>${s.caseId==='baile'&&s.interlude?`<p>No baile, você escolheu entregar ${s.interlude==='risada'?'sua risada':s.interlude==='reflexo'?'seu reflexo':'seu nome'} à própria sombra.</p>`:''}</div><div class="notice"><b>Mundo persistente:</b> confiança ${worldStats().trust}% · estabilidade ${worldStats().veil}% · ${worldStats().research} registros. Alguns casos futuros reconhecerão sua decisão.</div><div class="creditReward">${s.rewardLast?'✧ +'+s.rewardLast+' créditos recebidos pela primeira conclusão.':'✧ Recompensa deste arquivo já recebida.'}<br><small>Saldo: ${saved.wallet} ◈ · Sem compras obrigatórias</small></div>${net.mode==='versus'?rankTable():net.mode==='coop'?`<div class="notice"><b>Missão em equipe:</b> ${specialistCount()} pareceres registrados de ${net.size} pesquisadores.</div>`:''}${sequelOf(s.caseId)?`<button class="btn sequelCTA" data-case="${sequelOf(s.caseId)}">✦ Iniciar continuação desbloqueada →</button>`:''}<button class="btn outline" data-view="shop">Visitar a loja · ${saved.wallet} ◈</button><button class="btn" data-view="bestiary">Abrir bestiário →</button><button class="btn outline" data-view="collection">${net.role==='host'?'Selecionar novo caso para a equipe →':'Escolher outro caso →'}</button>${!isMulti()?'<button class="btn ghost" data-action="reset">Reinvestigar este caso</button>':''}</section>`}
function bestiary(){return `<section class="section"><div class="eyebrow">Compêndio do Instituto</div><h2>Bestiário</h2><p>${keys.length} registros associados às investigações do Instituto. As fichas são reveladas após a conclusão de cada investigação.</p>${keys.map(id=>{let cc=CASES[id];let known=s.caseId===id&&s.outcome||saved.cases?.[id]?.outcome;return `<div class="bestiaryCard"><img src="${cc.creatureImage}" alt="${known?cc.creature:'Criatura não identificada'}" style="${known?'':'filter:brightness(.12) saturate(.2)'}"/><div><div class="eyebrow">Registro ${cc.number}</div><h3>${known?cc.creature:'??? · espécie desconhecida'}</h3><p>${known?cc.creatureText:'Conclua o arquivo para revelar a identidade.'}</p><button class="smallBtn" data-case="${id}" ${net.online&&net.role==='guest'||!eligible(id)?'disabled':''}>${!eligible(id)?'Bloqueado':known?'Rever caso':'Investigar'} →</button></div></div>`}).join('')}</section>`}
function interludePage(){const choices={risada:{title:'Emprestei minha risada',result:'Seu reflexo ri alguns segundos antes de você. Uma máscara se abre: por dentro está escrito o nome de todos os que ainda dançam.',clue:'mascara'},reflexo:{title:'Emprestei meu reflexo',result:'O reflexo deixa o espelho e volta carregando um convite que você nunca recebeu. Ele parece orgulhoso de si.',clue:'convite'},nome:{title:'Emprestei meu nome',result:'Todos os relógios passam a chamar você de Quinta-feira. Um deles entrega uma anotação dourada antes de se desculpar.',clue:'relogio'}};let r=s.interlude?choices[s.interlude]:null;return `<div class="surrealHero"><div class="surrealSmile">☾</div><span>O BAILE NÃO OBEDECE À LÓGICA</span><h2>A sombra que dançava melhor</h2></div><section class="section"><button class="backBtn" data-view="hub">← Voltar à festa</button>${r?`<div class="eyebrow">Momento impossível · Registrado</div><h2>${r.title}</h2><p class="lead">${r.result}</p><div class="notice">✦ Você recebeu uma nova pista e 10 pontos pela curiosidade. Este encontro ficou registrado no relatório.</div>`:`<h2>Uma pergunta muito séria, feita por ninguém.</h2><p class="lead">Uma sombra com seus sapatos se aproxima, ajusta a gravata e pergunta: <em>“Qual parte de você posso levar para a pista de dança?”</em></p><p>Escolha uma resposta. O salão vai reagir — e lhe entregar uma pista diferente.</p>${Object.entries(choices).map(([id,o],i)=>`<button class="option" data-surreal="${id}"><b>${['✦','◇','☼'][i]}</b><span>${['Minha risada','Meu reflexo','Meu nome'][i]}</span></button>`).join('')}`}<button class="btn" data-view="hub">Voltar ao baile →</button></section>`}
function puzzle(){if(!c().puzzle)return hub();let colors=[['violeta','Violeta','#a984f4'],['dourado','Dourado','#e9c16f'],['azul','Azul','#75d3ec']];return `<div class="puzzleHero"><div class="puzzleOrbit"></div><span>ARQUIVO 002 · ANOMALIA SENSORIAL</span><h2>${c().puzzleTitle}</h2></div><section class="section"><button class="backBtn" data-view="hub">← Voltar ao salão</button><p class="lead">${c().puzzleMessage}</p><div class="briefQuote">${c().puzzleHint}</div>${s.puzzleSolved?`<div class="notice">✦ O ritmo foi decifrado. O salão mostra uma porta de saída, e você ganhou 25 pontos de pesquisa.</div>`:`<div class="rhythmSequence">${[0,1,2].map((v)=>`<span class="rhythmStep">${s.puzzleInput[v]?colors.find(k=>k[0]===s.puzzleInput[v])[1]:'?'}</span>`).join('')}</div><div class="colorPicks">${colors.map(([key,name,color])=>`<button data-color="${key}" class="colorPick" style="--color:${color}"><span></span>${name}</button>`).join('')}</div><p class="caption">Toque nas três cores. Se errar, a sequência reinicia. Sem contagem regressiva.</p><button class="btn ghost" data-action="puzzle-clear">Apagar sequência</button>`}<button class="btn" data-view="hub">${s.puzzleSolved?'Voltar à investigação':'Investigar outras pistas'} →</button></section>`}
function shop(){return `<section class="section gearStore"><button class="backBtn" data-view="${s.shopReturn||'collection'}">← Arquivos / investigação</button><div class="eyebrow">Divisão de equipamentos · Instituto do Véu</div><h2>Arsenal do Pesquisador</h2><div class="creditVault"><span>SEUS CRÉDITOS</span><strong>${saved.wallet} ◈</strong><small>Primeira conclusão de cada caso: +70 / +90 / +125, mais 20 por dedução correta. Rejogar não gera novos créditos.</small></div><p>Compre recursos para vasculhar cenários, ouvir segredos e proteger pessoas. Ferramentas permanentes valem para todos os casos. Os suprimentos são usados uma vez.</p><div class="gearGrid">${Object.entries(GEAR).map(([id,g])=>{const bought=g.type==='permanent'&&own(id),units=g.type==='consumable'?charges(id):0,canBuy=saved.wallet>=g.price&&!bought;return `<article class="gearCard"><div class="gearArt gearArt-${id}"><img src="${g.art}" alt="Ilustração de ${g.name}"/></div><div class="gearInfo"><div class="eyebrow">${g.tag} · ${g.type==='permanent'?'PERMANENTE':'CONSUMÍVEL'}</div><h3>${g.name}</h3><p>${g.desc}</p><div class="gearEffect">${g.effect}</div><button class="buyGear" data-buy="${id}" ${canBuy?'':'disabled'}>${bought?'✓ Adquirido':g.type==='consumable'&&units?'Comprar mais · '+g.price+' ◈ ('+units+' guardados)':'Comprar · '+g.price+' ◈'}</button></div></article>`}).join('')}</div><div class="notice">O inventário e os créditos são salvos neste navegador. Em grupo, cada jogador compra seus próprios equipamentos; descobertas e negociações são compartilhadas no cooperativo.</div><button class="btn outline" data-view="office">♜ Melhorar a sede / obter créditos →</button><button class="btn" data-view="${s.shopReturn||'collection'}">Voltar à pesquisa →</button></section>`}
function gearScan(){const id=s.caseId;if(!own('lens')||gearOn('lens')||s.activeScene!==gearScene()||s.outcome)return; s.gearFlags.lens=true;persist();toast('Assinatura espectral catalogada!');render();}
function gearRecord(){if(!own('recorder')||gearOn('recorder')||s.outcome)return;s.gearFlags.recorder=true;s.trust=trustNow();persist();toast('Depoimento secreto registrado!');render();}
function gearCompass(){if(!own('compass')||gearOn('compass')||s.outcome)return;s.gearFlags.compass=true;persist();render();}
function gearAmulet(){if(!own('amulet')||gearOn('amulet')||s.outcome)return;s.gearFlags.amulet=true;s.trust=trustNow();persist();toast('Pacto proposto: +2 de confiança.');render();}
function gearPowder(){if(!charges('powder')||s.outcome)return;const loc=c().scenes[s.activeScene],missing=loc?.items?.find(id=>!s.evidence.includes(id)&&canInspect(id));if(!missing){toast('Todas as pistas deste local já foram encontradas.');return;}saved.stock.powder--;s.evidence.push(missing);s.powderUses=(s.powderUses||0)+1;s.powdered=[...(s.powdered||[]),missing];s.modal=missing;persist();toast('O pó encontrou uma pista escondida.');render();}
function gearWard(){if(!charges('ward')||gearOn('ward')||s.outcome)return;saved.stock.ward--;s.gearFlags.ward=true;persist();toast('Selo de proteção ativo para este confronto.');render();}
function gearSceneTools(){const target=s.activeScene===gearScene(),loc=c().scenes[s.activeScene],available=loc.items.some(id=>!s.evidence.includes(id)&&canInspect(id));return `<div class="equipmentActions"><div class="eyebrow">Equipamentos de campo</div>${target?`<div class="equipHint">O ambiente guarda uma assinatura que uma Lente Espectral poderia analisar.</div>${own('lens')?`<button class="toolAction" data-gear="lens" ${gearOn('lens')||s.outcome?'disabled':''}>◉ ${gearOn('lens')?'✓ Assinatura sobrenatural identificada':'Usar Lente Espectral · revelar registro oculto'}</button>`:`<button class="toolAction" data-view="shop">◉ Lente Espectral não adquirida · Loja →</button>`}`:''}<button class="toolAction" data-gear="powder" ${charges('powder')&&!s.outcome&&available?'':'disabled'}>✴ Pó de Rastros · revelar uma pista (${charges('powder')} disponível)</button>${own('camera')?`<button class="toolAction" data-gear="camera" ${gearOn('camera')||s.outcome||!available?'disabled':''}>▣ ${gearOn('camera')?'✓ Fotografia registrada':'Fotografar indício da cena · uma vez por missão'}</button>`:''}<button class="toolAction" data-gear="lantern" ${charges('lantern')&&!s.outcome&&available?'':'disabled'}>✹ Iluminar vestígio (${charges('lantern')} disponíveis)</button>${gearOn('lantern')?`<p class="officeEvidence">${esc(FIELD_NOTES[s.caseId])}</p>`:''}<small>Ferramentas de cena respeitam as especializações do modo cooperativo. Nenhum item é obrigatório.</small></div>${officeTools()}`}
function modal(){if(!s.modal)return '';let e=c().clues[s.modal];if(!e)return '';return `<div class="modalLayer" data-dismiss="1"><div class="modalPanel" role="dialog" aria-modal="true" aria-label="Pista: ${esc(e.name)}"><button class="modalClose" data-action="close" aria-label="Fechar">×</button><div class="modalIndex">${s.powdered?.includes(s.modal)?"✴ DESCOBERTA COM PÓ DE RASTROS · ":"PISTA REGISTRADA · "}${c().number}</div><h2>${e.name}</h2><p>${e.detail}</p><div class="modalFact"><strong>NOTA DE CAMPO</strong><p>${e.insight}</p></div><button class="btn" data-action="close">Continuar investigando</button></div></div>`}
function render(){let map={title:cover,collection,roomMenu,room,brief,ritual,hub,scene,witness,dossier,board:researchBoard,theory:theories,confrontation,ending,bestiary,shop,office:officePage,contracts:contractsPage,puzzle,interlude:interludePage};let page=map[s.view]||cover;let full=['title','collection','brief','ritual','roomMenu','room','puzzle','shop','office','contracts'].includes(s.view)&&!(s.view==='office'&&(s.officeFromMission||net.inGame));document.body.classList.toggle('ballroom',s.caseId==='baile'&&s.phase===1&&s.pretty);app.innerHTML=(full?'':header())+`<main class="${full?'noNav':''}">${page()}</main>`+(full?'':nav())+modal()}
function chooseCase(id){if(!CASES[id]||!eligible(id)){toast('Arquivo bloqueado: conclua primeiro '+(CASES[CASES[id]?.prerequisite]?.short||'o caso anterior')+'.');return;}if(net.online){newMultiplayerCase(id);return}setupCase(id,false)}
function handleClick(ev){let target=ev.target.closest('[data-board-clue],[data-board-choice],[data-case],[data-scene],[data-view],[data-clue],[data-question],[data-theory],[data-end],[data-color],[data-surreal],[data-action],[data-buy],[data-gear],[data-office-buy],[data-office],[data-contract]');if(!target){if(ev.target.matches('[data-dismiss]')){s.modal=null;render()}return}
 if(target.disabled)return;
 if(target.dataset.boardClue){boardPick(target.dataset.boardClue);return}
 if(target.dataset.boardChoice!==undefined){boardAnswer(Number(target.dataset.boardChoice));return}
 if(target.dataset.officeBuy){upgradeRoom(target.dataset.officeBuy);return}
 if(target.dataset.office){if(target.dataset.office==='analysis')officeAnalysis();if(target.dataset.office==='index')officeIndex();return}
 if(target.dataset.contract){const [id,task]=target.dataset.contract.split(':');claimContract(id,task);return}
 if(target.dataset.buy){buyGear(target.dataset.buy);return}
 if(target.dataset.gear){let id=target.dataset.gear;({lens:gearScan,recorder:gearRecord,compass:gearCompass,amulet:gearAmulet,powder:gearPowder,ward:gearWard,camera:gearCamera,pendulum:gearPendulum,incense:gearIncense,lantern:gearLantern}[id]||(()=>{}))();return}
 if(target.dataset.case){chooseCase(target.dataset.case);return}
 if(target.dataset.scene){s.activeScene=target.dataset.scene;move('scene');return}
 if(target.dataset.view){if(target.dataset.view==='collection'&&net.online&&net.role==='guest'){toast('Aguarde a pessoa que criou a sala escolher o caso.');return}move(target.dataset.view);return}
 if(target.dataset.clue){let id=target.dataset.clue;if(!canInspect(id)&&!s.evidence.includes(id)){toast('Esta pista exige a especialidade da sua equipe.');return}if(!s.evidence.includes(id)){s.evidence.push(id);persist();playEffect('find')}s.modal=id;render();return}
 if(target.dataset.question){let id=target.dataset.question;s.reply=id;if(!s.witness.includes(id)){s.witness.push(id);s.trust=trustNow();persist()}render();return}
 if(target.dataset.theory){s.selectedTheory=target.dataset.theory;persist();render();return}
 if(target.dataset.end){voteEnd(target.dataset.end);return}
 if(target.dataset.surreal){let choice=target.dataset.surreal;const lookup={risada:'mascara',reflexo:'convite',nome:'relogio'};if(s.caseId==='baile'&&!s.interlude&&lookup[choice]){s.interlude=choice;if(!s.evidence.includes(lookup[choice]))s.evidence.push(lookup[choice]);persist();toast('A sombra registrou uma pista adicional.');render()}return}
 if(target.dataset.color){let color=target.dataset.color;if(s.puzzleSolved||!c().puzzle)return;s.puzzleInput.push(color);if(s.puzzleInput.length===3){if(s.puzzleInput.join(',')===c().puzzle.join(',')){s.puzzleSolved=true;toast('✦ A música encontra um ritmo impossível!');persist()}else{toast('As cores se desmancharam. Tente outra sequência.');s.puzzleInput=[]}}render();return}
 const a=target.dataset.action;
 if(a==='board-check'){boardCheck();return}
 if(a==='claim-echo'){claimEcho();return}
 if(a==='continue'){move(s.outcome?'ending':s.evidence.length?'hub':'brief');return}
 if(a==='begin'){move(c().ritual&&!s.ritualComplete?'ritual':'hub');return}
 if(a==='ritual'){s.ritualComplete=true;s.phase=1;persist();move('hub');toast('Você passou a enxergar o outro lado da festa.');return}
 if(a==='phase'){s.phase=1-s.phase;persist();render();if(s.caseId==='baile')toast(s.phase?'Você ouve cores e vê ecos.':'O salão recupera suas proporções usuais.');return}
 if(a==='effects'){s.pretty=!s.pretty;persist();render();toast(s.pretty?'Efeitos visuais ativados.':'Efeitos visuais reduzidos.');return}
 if(a==='audio'){ambientToggle();return}
 if(a==='soundtrack'){changeSoundtrack();return}
 if(a==='claim-daily'){claimDaily();return}
 if(a==='confirm'){voteTheory();return}
 if(a==='puzzle-clear'){s.puzzleInput=[];render();return}
 if(a==='reset'){if(!confirm('Recomeçar este caso? As pistas serão apagadas, mas a continuação permanecerá desbloqueada.'))return;saved.cases[s.caseId]=blank(s.caseId);setupCase(s.caseId,true);return}
 if(a==='close'){s.modal=null;render();return}
 if(a==='role-report'){roleReportAction();return}
 if(a==='start-party'){newMultiplayerCase(net.caseId);return}
 if(a==='multiplayer'){if(net.online){toast('Você já está em uma sala.');return}move('roomMenu');return}
 if(a==='host'){makeRoom();return}
 if(a==='join'){enterRoom();return}
 if(a==='copy-room'){let link=location.protocol==='https:'?location.href.split('?')[0]+'?room='+net.room:net.room;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(link).then(()=>toast('Convite copiado!')).catch(()=>toast('Código: '+net.room));else toast('Código: '+net.room);return}
 if(a==='leave-room'){closeNet();s=hydrate(saved.current);move('collection');return}
}
app.addEventListener('click',handleClick);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&s.modal){s.modal=null;render()}});
const invite=new URLSearchParams(location.search);if(invite.get('room')&&/^[A-Z0-9]{6}$/i.test(invite.get('room'))){s.view='roomMenu';net.status='Convite recebido. Digite o codinome e entre.'}
render();
